cat > tests/export-access.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { handleExport, exportNames } from '../src/server.js';

// CONTRIBUTING.md, "書き出しを見せてよい相手": the holiday calendar is the only
// export a guest may see. This walks every registered export, so an export
// added without `requireRole(req, STAFF)` fails here (#14 and #15 were both
// that mistake, reported one export at a time).
const GUEST_VISIBLE = ['holidays'];

test('every guest-visible export is a registered export', () => {
  for (const name of GUEST_VISIBLE) assert.ok(exportNames().includes(name), name);
});

for (const name of exportNames()) {
  const guestStatus = GUEST_VISIBLE.includes(name) ? 200 : 403;

  test(`a guest gets ${guestStatus} for the ${name} export`, () => {
    const res = handleExport(name, { role: 'guest' });
    assert.equal(res.status, guestStatus);
    if (guestStatus === 403) assert.deepEqual(res.body, { error: 'forbidden' });
  });

  test(`a caller without a known role gets ${guestStatus} for the ${name} export`, () => {
    assert.equal(handleExport(name, {}).status, guestStatus);
    assert.equal(handleExport(name, { role: 'stranger' }).status, guestStatus);
  });

  for (const role of ['admin', 'member']) {
    test(`a ${role} downloads the ${name} export`, () => {
      const res = handleExport(name, { role });
      assert.equal(res.status, 200);
      assert.ok(Array.isArray(res.body) && res.body.length > 0);
    });
  }
}
EOF
