import { test } from 'node:test';
import assert from 'node:assert/strict';
import { handleExport } from '../src/server.js';

// #15: the timesheets export is for the team only.
test('a guest may not download the timesheets', () => {
  const res = handleExport('timesheets', { role: 'guest' });
  assert.equal(res.status, 403);
  assert.deepEqual(res.body, { error: 'forbidden' });
});

for (const role of ['admin', 'member']) {
  test(`a ${role} downloads the timesheets`, () => {
    const res = handleExport('timesheets', { role });
    assert.equal(res.status, 200);
    assert.equal(res.body.length, 2);
  });
}
